   2	 * RAG (Retrieval-Augmented Generation) — Vector storage and embedding abstractions.
   3	 *
   4	 * Provides a VectorStore interface for similarity search and an EmbeddingAdapter
   5	 * interface for converting text into vector representations.  Concrete backends
   6	 * (local SQLite, remote API) implement these interfaces so that the RAG pipeline
   7	 * is backend-agnostic.
   8	 */
   9	
  10	// ── Vector Document Types ────────────────────────────────────────────────────
  11	
  12	/** A document stored in the vector store with its embedding. */
  13	export interface VectorDocument {
  14	  /** Unique document ID */
  15	  id: string;
  16	  /** Original text content */
  17	  content: string;
  18	  /** Pre-computed embedding vector */
  19	  embedding: number[];
  20	  /** Optional metadata (source file, tags, etc.) */
  21	  metadata?: Record<string, unknown>;
  22	  /** ISO timestamp of creation */
  23	  createdAt: string;
  24	  /** ISO timestamp of last update */
  25	  updatedAt: string;
  26	}
  27	
  28	/** Minimal input required to add a document (embedding is computed by the adapter). */
  29	export interface VectorDocumentInput {
  30	  /** Unique document ID (auto-generated if omitted) */
  31	  id?: string;
  32	  /** Text content to embed and store */
  33	  content: string;
  34	  /** Optional metadata */
  35	  metadata?: Record<string, unknown>;
  36	}
  37	
  38	// ── Query Types ──────────────────────────────────────────────────────────────
  39	
  40	/** Options for a similarity search query. */
  41	export interface VectorQuery {
  42	  /** The query text (will be embedded by the adapter) or a pre-computed vector */
  43	  text?: string;
