  85	const EXTENSION_MAP: Record<string, SupportedFileType> = {
  86	  ".md": "markdown",
  87	  ".mdx": "markdown",
  88	  ".json": "json",
  89	  ".jsonl": "json",
  90	  ".ts": "typescript",
  91	  ".tsx": "typescript",
  92	  ".js": "text",
  93	  ".jsx": "text",
  94	  ".mjs": "text",
  95	  ".cjs": "text",
  96	  ".txt": "text",
  97	  ".log": "text",
  98	  ".yaml": "text",
  99	  ".yml": "text",
